#include "model_render_inputs_candidate.h"
#include <iostream>
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=3)throw std::runtime_error("model base and mount required");auto read=[](std::string path){std::ifstream file(path,std::ios::binary);if(!file)throw std::runtime_error("fixture missing");return std::vector<uint8_t>((std::istreambuf_iterator<char>(file)),{});};std::string base=argv[1];auto model=readSfmModelGeometryCandidate(read(base+".mdl"),read(base+".vvd"),read(base+".dx90.vtx"));auto inputs=prepareModelRenderInputsCandidate(model,0,{argv[2]},2);size_t cursor=0;for(size_t n=0;n<model.meshes.size();++n){auto&r=inputs.ranges.at(n);auto&m=model.meshes[n];if(r.firstIndex!=cursor||r.indexCount!=m.triangles.size()*3||r.body!=m.body||r.model!=m.model||r.mesh!=m.mesh)throw std::runtime_error("mesh range mismatch");auto&material=inputs.materials.at(r.materialIndex);auto expected=resolveMountedModelMaterialCandidate(model.materials,0,m.material,{argv[2]});if(material.source.vmt!=expected.vmt||material.source.baseTexture!=expected.baseTexture)throw std::runtime_error("mesh material mismatch");for(auto&t:m.triangles)for(auto v:t)if(inputs.indices.at(cursor++)!=v)throw std::runtime_error("index order mismatch");}size_t bytes=0;for(auto&m:inputs.materials){if(m.image.rgba.size()!=size_t(m.image.width)*m.image.height*4)throw std::runtime_error("texture dimensions");bytes+=m.image.rgba.size();std::cout<<m.source.vmt.filename().string()<<" "<<m.image.width<<'x'<<m.image.height<<'\n';}if(inputs.materials.size()!=7||cursor!=198438)throw std::runtime_error("fixture totals");std::cout<<"x64 render inputs passed ranges="<<inputs.ranges.size()<<" indices="<<cursor<<" materials="<<inputs.materials.size()<<" rgba_bytes="<<bytes<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
